const titles=['目的と読み手を決める','構成を試作する','読みやすさを確認する','気づきと改善点をまとめる'];
const actions=['誰に何を伝えたいか書き出す','見出しと画像の配置を試す','文字の大きさと余白を見比べる','試作を振り返り、次に直すことを記録する'];
let states=['done','done','current','todo'];
let dates=['','','',''];
let understanding=['自分で説明できる','復習したい','未確認','未確認'];
function render(){document.querySelector('#understanding-summary').textContent='どう理解したか：'+understanding.filter(x=>x!=='未確認').length+'項目に記録 ／ 復習したい '+understanding.filter(x=>x==='復習したい').length+'件';const n=states.filter(s=>s==='done').length;let i=states.indexOf('current');if(i<0)i=states.indexOf('todo');document.querySelector('#count').textContent=`${n} / 4項目`;document.querySelector('#percent').textContent=`${n*25}%`;document.querySelector('#progress').value=n;document.querySelector('#current').textContent=i<0?'確認中・未確認の項目はありません':titles[i];document.querySelector('#next').textContent=i<0?'保留項目または次の学習目標を確認する':actions[i];document.querySelector('#steps').innerHTML=`<p>保留 ${states.filter(s=>s==='held').length}件（未完了に含む）</p><table class="course-table"><thead><tr><th class="chapter-col">章</th><th>確認項目</th><th>状態</th><th class="date-col">完了日</th></tr></thead><tbody>${titles.map((t,j)=>`<tr><td class="chapter-col">サンプル</td><td><small class="mobile-chapter">サンプル</small><button class="item-link" data-detail="${j}">${t}</button><small class="understanding-label">理解度：${understanding[j]}</small></td><td><select aria-label="${t}の状態" data-step="${j}">${Object.entries({todo:'未確認',current:'確認中',done:'完了',held:'保留'}).map(([v,label])=>`<option value="${v}" ${states[j]===v?'selected':''}>${label}</option>`).join('')}</select></td><td class="date-col">${dates[j]||'未設定'}</td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-step]').forEach(x=>x.onchange=()=>{const j=Number(x.dataset.step);states[j]=x.value;dates[j]=x.value==='done'?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date()):'';render()});document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>{const j=Number(x.dataset.detail);const d=document.querySelector('#detail');d.innerHTML=`<h3>${titles[j]}</h3><p>完了日：${dates[j]||'未設定'}</p><label>理解度<select id="understanding-select"><option>未確認</option><option>復習したい</option><option>自分で説明できる</option><option>自分で操作できる</option></select></label><p>体験用の表示です。保存・送信されません。</p><button id="close-detail">閉じる</button>`;d.showModal();document.querySelector('#understanding-select').value=understanding[j];document.querySelector('#understanding-select').onchange=ev=>{understanding[j]=ev.target.value;render()};document.querySelector('#close-detail').onclick=()=>d.close()});}
document.querySelector('#reset').onclick=()=>{states=['done','done','current','todo'];understanding=['自分で説明できる','復習したい','未確認','未確認'];dates=['','','',''];document.querySelector('#memo').value='';render()};const dialog=document.createElement('dialog');dialog.id='detail';document.body.append(dialog);render();
